class OrderServiceTest {

    MemberService memberService = new MemberServiceImpl();
    OrderService orderService = new OrderServiceImpl();

    @Test
    void VIP는_1000원_할인() {
        Long memberId = 1L;
        memberService.join(new Member(memberId, "memberVIP", Grade.VIP));

        Order order = orderService.createOrder(memberId, "itemA", 10000);

        assertThat(order.getDiscountPrice()).isEqualTo(1000);
        assertThat(order.calculatePrice()).isEqualTo(9000);
    }

    @Test
    void BASIC은_할인_없음() {
        Long memberId = 2L;
        memberService.join(new Member(memberId, "memberBasic", Grade.BASIC));

        Order order = orderService.createOrder(memberId, "itemA", 10000);

        assertThat(order.getDiscountPrice()).isEqualTo(0);
    }
}
